// Compare Apify pricing vs stored, build update + alert list
const actors = $input.all();
const registry = $('Split Registry Rows').all();

const updates = [];
const alerts = [];
const MAP = {'PAY_PER_EVENT':'pay_per_event','PAY_PER_RESULT':'pay_per_result','PRICE_PER_DATASET_ITEM':'pay_per_event','FLAT_PRICE_PER_MONTH':'flat_monthly','FREE':'compute_only'};

for (let i = 0; i < actors.length; i++) {
  const a = actors[i]?.json?.data;
  const r = registry[i]?.json;
  if (!r || !r.actor_slug) continue;

  if (!a) {
    // Actor fetch failed - possible deprecation or deletion
    alerts.push({
      severity: 'warn',
      slug: r.actor_slug,
      category: r.task_category,
      reason: 'actor_fetch_failed',
      action_required: 'Verify actor still exists in Apify Store'
    });
    continue;
  }

  const pi = (a.pricingInfos || []).sort((x,y) => (y.startedAt || '').localeCompare(x.startedAt || ''))[0] || {};
  const apifyPricing = pi.pricingModel || null;
  const stored = r.pricing_model;
  const mapped = apifyPricing ? MAP[apifyPricing] : 'compute_only';

  const row = {
    id: r.id,
    last_evaluated_at: new Date().toISOString()
  };

  // Pricing flip detection
  if (mapped !== stored) {
    row.pricing_model = mapped;
    if (mapped === 'flat_monthly' && !r.killed) {
      // Critical: actor converted to rental. Auto-kill + alert.
      row.killed = true;
      row.quality_notes = (r.quality_notes || '') + ' | AUTO-KILLED ' + new Date().toISOString().slice(0,10) + ': pricing flipped to FLAT_PRICE_PER_MONTH ($' + (pi.pricePerUnitUsd || '?') + '/mo)';
      alerts.push({
        severity: 'critical',
        slug: r.actor_slug,
        category: r.task_category,
        reason: 'pricing_flipped_to_rental',
        price: pi.pricePerUnitUsd,
        was_primary: r.is_primary,
        action_required: r.is_primary ? 'Promote a fallback to primary immediately' : 'Review and remove references'
      });
    } else {
      alerts.push({
        severity: 'info',
        slug: r.actor_slug,
        category: r.task_category,
        reason: 'pricing_model_changed',
        from: stored,
        to: mapped
      });
    }
  }

  // Deprecation check
  if (a.isDeprecated) {
    row.killed = true;
    alerts.push({
      severity: 'warn',
      slug: r.actor_slug,
      category: r.task_category,
      reason: 'actor_deprecated',
      action_required: r.is_primary ? 'Promote fallback, find replacement' : 'Remove references'
    });
  }

  if (Object.keys(row).length > 2) updates.push(row);  // > {id, last_evaluated_at}
}

return [{ json: { updates, alerts, summary: { actors_checked: actors.length, updates: updates.length, alerts: alerts.length, critical: alerts.filter(a => a.severity === 'critical').length } } }];

